package dev.horizonlab.parity;
import com.google.gson.*;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
import net.minecraft.core.*;import net.minecraft.core.component.*;import net.minecraft.core.registries.*;import net.minecraft.world.item.*;import net.minecraft.server.level.*;import net.minecraft.server.PlayerAdvancements;
/** Native BlocksAttacks durability dispatch into actual ItemStack storage. */
public final class VanillaBlockingItemDamageOracle {
    static final class Stop extends RuntimeException {}
    static Object unsafe;static Method allocate;static Field components,count;
    static <T>T make(Class<T> c)throws Exception{return c.cast(allocate.invoke(unsafe,c));}
    static Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
    static String optional(Object v){return v==null?"none":v.toString();}
    static String snapshot(ItemStack s){try{var c=(PatchedDataComponentMap)components.get(s);return count.getInt(s)+" "+s.getCount()+" "+optional(c.get(DataComponents.MAX_DAMAGE))+" "+optional(c.get(DataComponents.DAMAGE))+" "+c.has(DataComponents.UNBREAKABLE)+" "+s.getMaxDamage()+" "+s.getDamageValue()+" "+s.isEmpty()+" "+s.isDamageableItem()+" "+s.isDamaged()+" "+s.isBroken()+" "+s.nextDamageWillBreak();}catch(Exception e){throw new AssertionError(e);}}
    static void reset(ItemStack s,JsonObject f){s.setCount(f.get("count").getAsInt());if(f.get("max").isJsonNull())s.remove(DataComponents.MAX_DAMAGE);else s.set(DataComponents.MAX_DAMAGE,f.get("max").getAsInt());if(f.get("damage").isJsonNull())s.remove(DataComponents.DAMAGE);else s.set(DataComponents.DAMAGE,f.get("damage").getAsInt());if(f.get("unbreakable").getAsBoolean())s.set(DataComponents.UNBREAKABLE,net.minecraft.util.Unit.INSTANCE);else s.remove(DataComponents.UNBREAKABLE);}
    static float single(JsonElement v){return Float.intBitsToFloat(Integer.parseUnsignedInt(v.getAsString(),16));}
    static final class Data {Server level;JsonObject f;PrintWriter out;int calls;boolean changed;ItemStack stack;PlayerAdvancements advancements;
        void event(String s){out.println(s+" | "+snapshot(stack));int n=calls++;if(n==f.get("fail").getAsInt())throw new Stop();if(n==f.get("mutate_at").getAsInt()){changed=true;reset(stack,f.getAsJsonObject("after"));}}
        boolean flag(String name){return f.get((changed?"after_":"")+name).getAsBoolean();} boolean infinite(){return flag("infinite");}}
    static final class Server extends ServerLevel {Data d;Server(){super(null,null,null,null,null,null,false,0L,List.of(),false);}@Override public boolean isClientSide(){d.event("client");return d.flag("client");}}
    static final class Actor extends net.minecraft.world.entity.decoration.ArmorStand {Actor(){super(null,null);}}
    static void broken(Data d,ItemStack copy,net.minecraft.world.entity.EquipmentSlot slot){d.out.println("copy "+snapshot(copy));d.event("break "+(slot==net.minecraft.world.entity.EquipmentSlot.MAINHAND?0:1));}
    static void stat(Data d,net.minecraft.stats.Stat<?> s){if(s.getType()!=net.minecraft.stats.Stats.ITEM_USED)throw new AssertionError();d.event("stat "+(s.getValue()==Items.AIR?0:1));}
    static final class Human extends ServerPlayer {Data d;Human(){super(null,null,null,null);}@Override public boolean hasInfiniteMaterials(){d.event("infinite");return d.infinite();}@Override public PlayerAdvancements getAdvancements(){d.event("criterion");return d.advancements;}@Override public ServerLevel level(){d.event("level");return d.flag("server")?d.level:null;}@Override public void awardStat(net.minecraft.stats.Stat<?> s){stat(d,s);}@Override public void onEquippedItemBroken(ItemStack copy,net.minecraft.world.entity.EquipmentSlot slot){broken(d,copy,slot);}}
    static final class PlainPlayer extends net.minecraft.world.entity.player.Player {Data d;PlainPlayer(){super(null,null);}@Override public net.minecraft.world.level.GameType gameMode(){return net.minecraft.world.level.GameType.SURVIVAL;}@Override public boolean isSpectator(){return false;}@Override public boolean isCreative(){return false;}@Override public net.minecraft.world.level.Level level(){d.event("level");return d.flag("server")?d.level:null;}@Override public void awardStat(net.minecraft.stats.Stat<?> s){stat(d,s);}@Override public void onEquippedItemBroken(ItemStack copy,net.minecraft.world.entity.EquipmentSlot slot){broken(d,copy,slot);}}
    public static void main(String[] args)throws Exception{
        net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();var u=Class.forName("sun.misc.Unsafe");unsafe=field(u,"theUnsafe").get(null);allocate=u.getMethod("allocateInstance",Class.class);components=field(ItemStack.class,"components");count=field(ItemStack.class,"count");var ctor=ItemStack.class.getDeclaredConstructor(Holder.class,int.class,PatchedDataComponentMap.class);ctor.setAccessible(true);Path dir=Path.of(args[1]);
        try(var out=new PrintWriter(Files.newBufferedWriter(dir.resolve(args[0]+".txt")));var lines=Files.lines(dir.resolve("inputs.txt"))){for(var line:(Iterable<String>)lines::iterator){var d=new Data();d.f=JsonParser.parseString(line).getAsJsonObject();d.out=out;d.advancements=make(PlayerAdvancements.class);field(PlayerAdvancements.class,"activeTriggers").set(d.advancements,new HashMap<>());d.level=make(Server.class);d.level.d=d;var human=make(Human.class);human.d=d;var plain=make(PlainPlayer.class);plain.d=d;net.minecraft.world.entity.LivingEntity actor=switch(d.f.get("kind").getAsInt()){case 0->make(Actor.class);case 1->plain;default->human;};d.stack=(ItemStack)ctor.newInstance(BuiltInRegistries.ITEM.wrapAsHolder(d.f.get("air").getAsBoolean()?Items.AIR:Items.SHIELD),1,new PatchedDataComponentMap(DataComponentMap.EMPTY));reset(d.stack,d.f.getAsJsonObject("initial"));var rule=d.f.getAsJsonObject("rule");var component=new net.minecraft.world.item.component.BlocksAttacks(0,1,List.of(),new net.minecraft.world.item.component.BlocksAttacks.ItemDamageFunction(single(rule.get("threshold")),single(rule.get("base")),single(rule.get("factor"))),Optional.empty(),Optional.empty(),Optional.empty());
            try{component.hurtBlockingItem(d.level,d.stack,actor,net.minecraft.world.InteractionHand.values()[d.f.get("hand").getAsInt()],single(d.f.get("damage")));out.println("result ok");}catch(Stop e){out.println("result error");}out.println("state "+snapshot(d.stack)+" "+d.calls+" "+d.changed);
        }}
    }
}
